codeSnippet.code:
// Primitivos são copiados por valor:
let a = 10;
let b = a;
b = 20;
console.log(a); // 10 (permanece intacto)

// Objetos são copiados por referência:
let obj1 = { valor: 10 };
let obj2 = obj1;
obj2.valor = 20;
console.log(obj1.valor); // 20 (compartilham a mesma referência em memória)
